import React, { useState } from 'react';

const QuizPage = () => {
  const [formData, setFormData] = useState({
    subject: '',
    examType: '',
    classYear: '',
    topics: [],
    difficultyLevels: [],
    customTimeLimits: {},
    quizMode: '',
    addHints: false,
    adaptiveDifficulty: false,
    answerExplanation: false,
    questionSource: '',
    examMode: false,
    breakIntoSubtopics: false,
    studentName: '',
    randomizeOrder: false,
    allowRetry: false,
  });

  // Handle changes for different inputs
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleMultiChange = (e) => {
    const { value, checked } = e.target;
    if (checked) {
      setFormData((prevData) => ({
        ...prevData,
        topics: [...prevData.topics, value],
      }));
    } else {
      setFormData((prevData) => ({
        ...prevData,
        topics: prevData.topics.filter((topic) => topic !== value),
      }));
    }
  };

  const handleDifficultyChange = (e) => {
    const { value, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      difficultyLevels: checked
        ? [...prevData.difficultyLevels, value]
        : prevData.difficultyLevels.filter((level) => level !== value),
    }));
  };

  const handleTimeLimitChange = (e, topic) => {
    setFormData((prevData) => ({
      ...prevData,
      customTimeLimits: {
        ...prevData.customTimeLimits,
        [topic]: e.target.value,
      },
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle form submission (e.g., send data to backend)
    console.log(formData);
  };

  return (
    <div className="p-6 max-w-3xl mx-auto bg-white shadow-md rounded-lg">
      <h2 className="text-2xl font-bold mb-6">Quiz Configuration</h2>


    </div>
  );
};

export default QuizPage;
